// Webhook delivery attempts
type WebhookDelivery struct {
	ID             uuid.UUID `db:"id" json:"id"`
	EventID        uuid.UUID `db:"event_id" json:"event_id"`
	SubscriptionID uuid.UUID `db:"subscription_id" json:"subscription_id"`
	// Delivery URL (snapshot at time of delivery)
	EndpointUrl string `db:"endpoint_url" json:"endpoint_url"`
	// Delivery status: pending, delivered, failed, dlq
	Status string `db:"status" json:"status"`
	// Number of delivery attempts
	Attempts      int32              `db:"attempts" json:"attempts"`
	LastAttemptAt pgtype.Timestamptz `db:"last_attempt_at" json:"last_attempt_at"`
	// Next retry timestamp (for pending deliveries)
	NextRetryAt    pgtype.Timestamptz `db:"next_retry_at" json:"next_retry_at"`
	ResponseStatus *int32             `db:"response_status" json:"response_status"`
	// Response body (truncated to 1000 chars)
	ResponseBodyPreview *string `db:"response_body_preview" json:"response_body_preview"`
	// Response time in milliseconds
	ResponseTimeMs *int32             `db:"response_time_ms" json:"response_time_ms"`
	ErrorMessage   *string            `db:"error_message" json:"error_message"`
	CreatedAt      pgtype.Timestamptz `db:"created_at" json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `db:"updated_at" json:"updated_at"`
}

// Customer webhook endpoint registrations
type WebhookEndpoint struct {
	ID             uuid.UUID `db:"id" json:"id"`
	OrganizationID uuid.UUID `db:"organization_id" json:"organization_id"`
	// Webhook URL (HTTPS required in production)
	Url string `db:"url" json:"url"`
	// HMAC secret hash for signature verification
	SecretHash  string             `db:"secret_hash" json:"secret_hash"`
	Description *string            `db:"description" json:"description"`
	IsActive    bool               `db:"is_active" json:"is_active"`
	CreatedAt   pgtype.Timestamptz `db:"created_at" json:"created_at"`
	UpdatedAt   pgtype.Timestamptz `db:"updated_at" json:"updated_at"`
}

// Generated webhook events
type WebhookEvent struct {
	ID             uuid.UUID `db:"id" json:"id"`
	OrganizationID uuid.UUID `db:"organization_id" json:"organization_id"`
	EventType      string    `db:"event_type" json:"event_type"`
	// Resource type (shipment, billing, etc.)
	ResourceType string `db:"resource_type" json:"resource_type"`
	// Resource identifier
	ResourceID uuid.UUID `db:"resource_id" json:"resource_id"`
	// Event payload as JSON
	Payload   json.RawMessage    `db:"payload" json:"payload"`
	CreatedAt pgtype.Timestamptz `db:"created_at" json:"created_at"`
}

// Event type subscriptions for endpoints
type WebhookSubscription struct {
	ID         uuid.UUID `db:"id" json:"id"`
	EndpointID uuid.UUID `db:"endpoint_id" json:"endpoint_id"`
	// Event type (e.g., "shipment.delivered", "billing.topup.completed")
	EventType string             `db:"event_type" json:"event_type"`
	IsActive  bool               `db:"is_active" json:"is_active"`
	CreatedAt pgtype.Timestamptz `db:"created_at" json:"created_at"`
}
